mapper.select:
	SELECT 	 DCTNAME, --字典名   
             DCTVALUE --字典值 
        FROM T_ECC_DICTIONARY D
       WHERE 1=1
       AND D.DCTROOTTYPE =#{dctRootType}
       AND D.DCTFATHTYPE =#{dctFathType}
       AND D.DCTLEFTTYPE =#{dctLeftType}
       ORDER BY DCTSORTNO

mapper.update:
	    UPDATE  T_ECC_DICTIONARY D

             D.STAT = #{stat}

		WHERE

			D.DCTID = #{dctId}

mapper.select:
SELECT NVL(COUNT(DCTVALUE),0) 
     FROM T_ECC_DICTIONARY
WHERE  1=1
     AND DCTROOTTYPE = #{dctRootType}
     AND DCTFATHTYPE = #{dctFathType}
     AND DCTLEFTTYPE = #{dctLeftType}
     AND DCTVALUE = #{dctValue}

  	AND DCTVALUE <> #{oldDctValue} 

  	AND STAT <> #{stat}

SELECT DCTVALUE 
  FROM T_ECC_DICTIONARY
WHERE DCTID = #{dctId}

