UPDATE T_ECC_DICTIONARY
DCTROOTTYPE = #{dctRootType}, DCTFATHTYPE = #{dctFathType}, DCTLEFTTYPE = #{dctLeftType}, DCTNAME = #{dctName}, DCTVALUE = #{dctValue}, DCTSORTNO = #{dctSortNo}, DCTISLEAF = #{dctIsLeaf}, DCTSTAT = #{dctStat}, STAT = #{stat}
